package studio.jiayu.neoagent;
public class DocumentTextTest {
 static int count;static void yes(boolean b){if(!b)throw new AssertionError("case "+count);count++;}
 public static void main(String[] args)throws Exception{String body="租赁合同\n甲方：[]\n租金每月5日前支付\n乙方签署：[]";yes(DocumentText.same(body,body));yes(DocumentText.same("\n"+body+"\n",body));yes(DocumentText.same(body.replace("\n","\r\n"),body));yes(!DocumentText.same(body+"\n日有优先承租权。",body));yes(!DocumentText.same("旧版合同\n"+body,body));yes(!DocumentText.same(body,body.replace("5","10")));yes(DocumentText.wholeSelection(body,body,0,0,body.length()));yes(DocumentText.wholeSelection(body,body,0,body.length(),0));yes(!DocumentText.wholeSelection(body,body,1,0,body.length()));yes(!DocumentText.wholeSelection(body,body,0,0,5));yes(!DocumentText.wholeSelection(body+"旧条款",body,0,0,body.length()));yes(!DocumentText.same("",""));yes(DocumentText.replaceOnce(body,"5日前","10日前").equals(body.replace("5日前","10日前")));boolean duplicate=false;try{DocumentText.replaceOnce("租金租金","租金","押金");}catch(Exception e){duplicate=true;}yes(duplicate);boolean missing=false;try{DocumentText.replaceOnce(body,"不存在的条款","变更");}catch(Exception e){missing=true;}yes(missing);System.out.println("PASS: "+count+" document whole-selection and exact-readback cases");}
}
